'use strict';

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const swaggerUi = require('swagger-ui-express');

const corsConfig = require('./config/cors');
const rateLimiter = require('./middlewares/rateLimiter');
const errorHandler = require('./middlewares/errorHandler');
const router = require('./routes');
const swaggerSpec = require('./docs/swagger');
const logger = require('./utils/logger');

const { PAYLOAD_LIMIT = '10kb', NODE_ENV = 'development' } = process.env;

const app = express();

app.use((req, res, next) => {
  const requestId = crypto.randomUUID();
  req.requestId = requestId;
  res.setHeader('X-Request-ID', requestId);
  next();
});

app.use(helmet());

app.use(cors(corsConfig));

app.use(rateLimiter);

app.use(express.json({ limit: PAYLOAD_LIMIT }));

app.use(express.urlencoded({ extended: false, limit: PAYLOAD_LIMIT }));

morgan.token('request-id', (req) => req.requestId);

const morganFormat = NODE_ENV === 'production' ? 'combined' : 'dev';
const morganOptions = {
  stream: {
    write: (message) => logger.http(message.trim()),
  },
};

if (NODE_ENV !== 'test') {
  app.use(morgan(morganFormat, morganOptions));
}

app.use('/api/v1', router);

app.use('/api-docs', swaggerUi.serve, swaggerUi.setup(swaggerSpec));

app.use((req, res, next) => {
  const error = new Error(`Ruta no encontrada: ${req.method} ${req.originalUrl}`);
  error.status = 404;
  next(error);
});

app.use(errorHandler);

module.exports = app;

// XP-9: Configuración base de la aplicación Express - Metodología Híbrida
// Este archivo forma parte de la capa de configuración según arquitectura RESTful MVC simplificado.

import express from 'express';
import helmet from 'helmet';
import cors from 'cors';
import morgan from 'morgan';

import rateLimiter from '../middlewares/rateLimiter.js';
import errorHandler from '../middlewares/errorHandler.js';
import apiRouter from '../routes/index.js';
import { swaggerUi, swaggerSpec } from '../docs/swagger.js';
import { morganStream } from '../utils/logger.js';

const CORS_ORIGIN = process.env.CORS_ORIGIN || 'http://localhost:3000';
const NODE_ENV = process.env.NODE_ENV || 'development';

const allowedOrigins = CORS_ORIGIN.split(',').map((origin) => origin.trim());

const corsOptions = {
  origin: allowedOrigins,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  credentials: true,
};

const morganFormat = NODE_ENV === 'production' ? 'combined' : 'dev';

const app = express();

// 1. Helmet - seguridad HTTP con headers por defecto
app.use(helmet());

// 2. CORS - orígenes permitidos y preflight
app.use(cors(corsOptions));
app.options('*', cors(corsOptions));

// 3. Rate Limiter - protección DoS/DDoS
app.use(rateLimiter);

// 4. Morgan - access logs HTTP redirigidos a winston
app.use(morgan(morganFormat, { stream: morganStream }));

// 5. express.json - parseo de body JSON con límite de 10kb
app.use(express.json({ limit: '10kb' }));

// 6. express.urlencoded - parseo de body URL-encoded con límite de 10kb
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// Montaje de rutas principales
app.use('/api/v1', apiRouter);

// Montaje de documentación Swagger UI
app.use('/api-docs', swaggerUi.serve, swaggerUi.setup(swaggerSpec));

// Manejador global de errores - debe ser el último middleware
app.use(errorHandler);

export default app;

const logger = require('../utils/logger');

const allowedOrigins = (process.env.ALLOWED_ORIGINS || '')
  .split(',')
  .map((origin) => origin.trim())
  .filter((origin) => origin.length > 0);

logger.info('CORS: Orígenes permitidos registrados', {
  origins: allowedOrigins,
  count: allowedOrigins.length,
  environment: process.env.NODE_ENV || 'development',
});

const originValidator = (origin, callback) => {
  if (!origin) {
    return callback(null, true);
  }

  if (allowedOrigins.includes(origin)) {
    return callback(null, true);
  }

  // ADVERTENCIA DE SEGURIDAD: En entorno de desarrollo se permite cualquier origen
  // para facilitar el trabajo local. NUNCA habilitar este comportamiento en producción.
  if (process.env.NODE_ENV === 'development') {
    logger.warn('CORS: Origen no registrado permitido en modo desarrollo', {
      origin,
      warning: 'Este comportamiento NO debe replicarse en producción',
    });
    return callback(null, true);
  }

  logger.warn('CORS: Solicitud bloqueada por política de origen cruzado', {
    origin,
    allowedOrigins,
  });

  return callback(
    new Error(
      `CORS: El origen '${origin}' no está autorizado por la política de seguridad de esta aplicación. ` +
        `Si necesitas acceso, contacta al administrador para agregar tu origen a ALLOWED_ORIGINS.`
    )
  );
};

const corsOptions = {
  origin: originValidator,

  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],

  allowedHeaders: ['Content-Type', 'Authorization', 'X-Request-ID'],

  exposedHeaders: ['X-Request-ID'],

  // Habilita el envío de cookies y headers de autorización en requests cross-origin
  credentials: true,

  // Se usa 200 en lugar del default 204 por compatibilidad con navegadores legacy (IE11)
  optionsSuccessStatus: 200,

  // Tiempo en segundos que el navegador puede cachear la respuesta preflight (24 horas)
  maxAge: parseInt(process.env.CORS_MAX_AGE, 10) || 86400,
};

module.exports = corsOptions;

require('dotenv').config();
const rateLimit = require('express-rate-limit');

// XP-9: Ventana de tiempo en ms para el rate limiting (default: 15 minutos)
const WINDOW_MS = parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || 900000;

// XP-9: Máximo de requests permitidos por IP en la ventana de tiempo (default: 100)
const MAX_REQUESTS = parseInt(process.env.RATE_LIMIT_MAX_REQUESTS, 10) || 100;

// XP-9: Entorno de ejecución para ajustar comportamiento del middleware
const NODE_ENV = process.env.NODE_ENV;

// XP-9: Configuración centralizada del middleware express-rate-limit
const rateLimitConfig = rateLimit({
  // Ventana de tiempo en milisegundos durante la cual se contabilizan los requests
  windowMs: WINDOW_MS,

  // Número máximo de requests permitidos por IP dentro de la ventana definida
  max: MAX_REQUESTS,

  // Incluye headers estándar RateLimit-Limit, RateLimit-Remaining y RateLimit-Reset
  // para transparencia hacia el cliente sobre el estado de su cuota
  standardHeaders: true,

  // Deshabilita los headers deprecados X-RateLimit-* para evitar redundancia
  legacyHeaders: false,

  // Objeto de mensaje estructurado retornado cuando se supera el límite
  message: {
    status: 429,
    error: 'Too Many Requests',
    message:
      'Has superado el límite de requests permitidos. Por favor, intenta nuevamente más tarde.',
    retryAfter: 'Consulta el header Retry-After para saber cuándo puedes reintentar.',
  },

  // XP-9: Handler personalizado que detiene la cadena de middlewares al superar el límite
  handler: (req, res, next, options) => {
    // Establece el header Retry-After en segundos (windowMs / 1000)
    res.setHeader('Retry-After', Math.ceil(WINDOW_MS / 1000));

    // Responde con status 429 y el objeto message estructurado como JSON
    res.status(429).json(options.message);

    // No se llama a next() para detener la cadena de middlewares intencionalmente
  },

  // XP-9: Omite el rate limiting en entorno de test para no interferir con Jest/Supertest
  skip: (req) => {
    return NODE_ENV === 'test';
  },

  // XP-9: Generador de clave por cliente, considera proxies y balanceadores de carga
  keyGenerator: (req) => {
    // Usa X-Forwarded-For si existe (entornos detrás de proxy/load balancer),
    // tomando el primer valor de la lista; de lo contrario usa req.ip directamente
    const forwardedFor = req.headers['x-forwarded-for'];

    if (forwardedFor) {
      return forwardedFor.split(',')[0].trim();
    }

    return req.ip;
  },
});

module.exports = rateLimitConfig;

