const { validationResult } = require('express-validator');
const { sign } = require('jsonwebtoken');
const logger = require('../utils/logger');
const { successResponse, errorResponse } = require('../utils/response');

const generateToken = async (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return errorResponse(res, 422, 'Errores de validación', errors.array());
  }

  const { username, password } = req.body;
  const requestId = req.requestId;

  const validUser = process.env.AUTH_TEST_USER;
  const validPassword = process.env.AUTH_TEST_PASSWORD;

  const usernameMatch = username === validUser;
  const passwordMatch = password === validPassword;

  await new Promise((resolve) => setTimeout(resolve, 50));

  if (!usernameMatch || !passwordMatch) {
    logger.warn('Intento de autenticación fallido', {
      username,
      requestId,
    });
    return errorResponse(res, 401, 'Credenciales inválidas');
  }

  try {
    const expiresIn = process.env.JWT_EXPIRES_IN || '1h';

    const payload = {
      sub: username,
      role: 'dev',
    };

    const token = sign(payload, process.env.JWT_SECRET, {
      expiresIn,
      algorithm: 'HS256',
    });

    logger.info('Token JWT generado exitosamente', {
      username,
      requestId,
    });

    return successResponse(res, 200, 'Token generado exitosamente', {
      token,
      expiresIn,
      tokenType: 'Bearer',
    });
  } catch (error) {
    next(error);
  }
};

module.exports = { generateToken };
module.exports.default = generateToken;

const logger = require('../utils/logger');
const { sendSuccess } = require('../utils/response');

const getHolaMundo = async (req, res, next) => {
  try {
    const requestId = req.requestId;

    const responseData = {
      message: 'Hola Mundo',
      timestamp: new Date().toISOString(),
      requestId,
    };

    logger.info('Endpoint GET /api/v1/hola invocado exitosamente', {
      requestId,
    });

    return sendSuccess(res, 200, responseData);
  } catch (error) {
    logger.error('Error inesperado en getHolaMundo', {
      requestId: req.requestId,
      message: error.message,
    });

    return next(error);
  }
};

module.exports = { getHolaMundo };

const jwt = require('jsonwebtoken');
const logger = require('../utils/logger');

const verifyToken = (req, res, next) => {
  const requestId = req.requestId || null;

  if (!process.env.JWT_SECRET) {
    logger.error('JWT_SECRET environment variable is not configured', { requestId });
    return res.status(500).json({
      success: false,
      message: 'Error interno del servidor: configuración de autenticación no disponible',
      requestId,
    });
  }

  const authHeader = req.headers['authorization'];

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    logger.warn('Authentication failed: missing or malformed Authorization header', {
      requestId,
      ip: req.ip,
    });
    return res.status(401).json({
      success: false,
      message: 'Token no proporcionado o formato incorrecto. Se requiere Authorization: Bearer <token>',
      requestId,
    });
  }

  const token = authHeader.split(' ')[1];

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;

    logger.debug('Authentication successful', {
      requestId,
      userId: decoded.id || decoded.sub || null,
    });

    return next();
  } catch (error) {
    if (error.name === 'TokenExpiredError') {
      logger.warn('Authentication failed: token expired', {
        requestId,
        ip: req.ip,
      });
      return res.status(401).json({
        success: false,
        message: 'El token ha expirado. Por favor, obtenga un nuevo token',
        requestId,
      });
    }

    if (error.name === 'JsonWebTokenError') {
      logger.warn('Authentication failed: invalid token', {
        requestId,
        ip: req.ip,
      });
      return res.status(401).json({
        success: false,
        message: 'Token inválido',
        requestId,
      });
    }

    logger.warn('Authentication failed: unexpected error during token verification', {
      requestId,
      ip: req.ip,
      errorName: error.name,
    });
    return res.status(500).json({
      success: false,
      message: 'Error interno al verificar el token',
      requestId,
    });
  }
};

module.exports = { verifyToken };

const logger = require('../utils/logger');

const errorHandler = (error, req, res, next) => {
  const isErrorObject = error !== null && typeof error === 'object';

  let statusCode = isErrorObject
    ? error.statusCode || error.status || 500
    : 500;

  let message = isErrorObject && error.message
    ? error.message
    : 'Internal Server Error';

  const validationErrors = isErrorObject && error.errors ? error.errors : null;

  const requestId = req.headers['x-request-id'] || null;

  if (isErrorObject && error instanceof SyntaxError && statusCode === 400) {
    message = 'Malformed JSON in request body';
  }

  if (statusCode < 400) {
    statusCode = 500;
  }

  const isProduction = process.env.NODE_ENV === 'production';

  const logPayload = {
    statusCode,
    message,
    requestId,
    method: req.method,
    url: req.originalUrl || req.url,
  };

  if (!isProduction) {
    logPayload.stack = isErrorObject && error.stack ? error.stack : undefined;
  }

  if (statusCode >= 500) {
    logger.error(logPayload);
  } else {
    logger.warn(logPayload);
  }

  const responseBody = {
    success: false,
    statusCode,
    message,
    requestId,
    errors: validationErrors,
  };

  if (!isProduction) {
    responseBody.stack = isErrorObject && error.stack ? error.stack : undefined;
  }

  res.status(statusCode).json(responseBody);
};

module.exports = errorHandler;

const crypto = require('crypto');
const morgan = require('morgan');
const logger = require('../utils/logger');

morgan.token('request-id', (req) => req.requestId);

const morganFormat = ':request-id :method :url :status :response-time ms :res[content-length]';

const morganStream = {
  write: (message) => {
    const trimmed = message.trim();
    if (trimmed) {
      logger.info(trimmed);
    }
  },
};

const morganMiddleware = morgan(morganFormat, { stream: morganStream });

const requestLogger = (req, res, next) => {
  req.requestId = crypto.randomUUID();
  res.setHeader('X-Request-ID', req.requestId);

  morganMiddleware(req, res, next);
};

module.exports = requestLogger;

const { validationResult } = require('express-validator');

const validateInput = (validationRules) => {
  return [
    ...validationRules,
    (req, res, next) => {
      const result = validationResult(req);
      if (!result.isEmpty()) {
        return res.status(422).json({
          success: false,
          error: 'Validation failed',
          errors: result.array().map((err) => ({
            field: err.path,
            message: err.msg,
          })),
          requestId: req.requestId || null,
        });
      }
      next();
    },
  ];
};

const validationSchemas = {
  generateToken: [
    require('express-validator').body('username')
      .trim()
      .escape()
      .notEmpty()
      .withMessage('El campo username no puede estar vacío')
      .isLength({ min: 3 })
      .withMessage('El username debe tener al menos 3 caracteres')
      .isLength({ max: 50 })
      .withMessage('El username no puede superar los 50 caracteres'),
    require('express-validator').body('password')
      .trim()
      .escape()
      .notEmpty()
      .withMessage('El campo password no puede estar vacío')
      .isLength({ min: 6 })
      .withMessage('El password debe tener al menos 6 caracteres'),
  ],
  holaEndpoint: [],
};

module.exports = { validateInput, validationSchemas };

const { Router } = require('express');
const authRoutes = require('./auth.routes');
const healthRoutes = require('./health.routes');
const holaRoutes = require('./hola.routes');

const router = Router();

router.use('/auth', authRoutes);
router.use('/health', healthRoutes);
router.use('/hola', holaRoutes);

module.exports = router;

const winston = require('winston');

// ADVERTENCIA DE SEGURIDAD (DevSecOps):
// Está PROHIBIDO pasar como argumentos a este logger:
// - Passwords o credenciales
// - Tokens JWT o API keys
// - Datos de tarjetas de crédito/débito
// - PII (Información Personal Identificable): emails, DNI, teléfonos, etc.
// - Cualquier otro dato sensible o confidencial
// El logger es un canal de observabilidad, no de almacenamiento de datos privados.

// NOTA: El directorio logs/ debe existir en la raíz del proyecto antes de ejecutar
// la aplicación en entornos distintos a test. Debe ser creado por el script de
// inicialización del proyecto. Agregar logs/ al .gitignore del repositorio.

const { combine, timestamp, colorize, simple, printf, json, errors } = winston.format;

const NODE_ENV = process.env.NODE_ENV || 'production';
const SERVICE_NAME = process.env.SERVICE_NAME || 'api-service';

// Determinar el nivel de log en tiempo de inicialización del módulo
const resolveLogLevel = () => {
  if (process.env.LOG_LEVEL) {
    return process.env.LOG_LEVEL;
  }
  if (NODE_ENV === 'development') {
    return 'debug';
  }
  return 'info';
};

const LOG_LEVEL = resolveLogLevel();

// Formato personalizado para desarrollo: legible, colorizado, con timestamp
const developmentFormat = combine(
  colorize({ all: true }),
  timestamp({ format: 'YYYY-MM-DDTHH:mm:ss.SSSZ' }),
  errors({ stack: true }),
  printf(({ timestamp: ts, level, message, stack, ...meta }) => {
    const metaStr = Object.keys(meta).length
      ? ` ${JSON.stringify(meta)}`
      : '';
    const stackStr = stack ? `\n${stack}` : '';
    return `${ts} [${level}]: ${message}${metaStr}${stackStr}`;
  })
);

// Formato JSON estructurado para producción y otros entornos (ISO 8601)
const productionFormat = combine(
  timestamp({ format: 'YYYY-MM-DDTHH:mm:ss.SSSZ' }),
  errors({ stack: true }),
  json()
);

// Seleccionar formato de consola según entorno
const consoleFormat = NODE_ENV === 'development' ? developmentFormat : productionFormat;

// Formato siempre JSON para archivos
const fileFormat = combine(
  timestamp({ format: 'YYYY-MM-DDTHH:mm:ss.SSSZ' }),
  errors({ stack: true }),
  json()
);

// Construir lista de transports
const transports = [];

// Console transport: siempre activo
transports.push(
  new winston.transports.Console({
    format: consoleFormat,
  })
);

// File transports: solo cuando NO es entorno de test
if (NODE_ENV !== 'test') {
  // Transport para errores únicamente
  transports.push(
    new winston.transports.File({
      filename: 'logs/error.log',
      level: 'error',
      format: fileFormat,
    })
  );

  // Transport para todos los niveles (combined)
  transports.push(
    new winston.transports.File({
      filename: 'logs/combined.log',
      format: fileFormat,
    })
  );
}

// Crear instancia del logger de winston
const logger = winston.createLogger({
  // Niveles npm por defecto: error(0), warn(1), info(2), http(3), verbose(4), debug(5), silly(6)
  level: LOG_LEVEL,
  levels: winston.config.npm.levels,
  defaultMeta: {
    service: SERVICE_NAME,
  },
  transports,
  // No salir del proceso ante excepciones no manejadas desde el logger
  exitOnError: false,
});

// Propiedad stream para integración con morgan
// Morgan delegará sus access logs a winston a través de este stream,
// unificando toda la salida de logs en un único canal.
logger.stream = {
  write: (message) => {
    // Eliminar el salto de línea final que agrega morgan
    logger.http(message.trimEnd());
  },
};

module.exports = logger;

export const sendSuccess = (res, data, message = 'Operation completed successfully', statusCode = 200, req = {}) => {
  const requestId = req.id || (req.headers && req.headers['x-request-id']) || 'no-request-id';

  const envelope = {
    success: true,
    data,
    message,
    timestamp: new Date().toISOString(),
    requestId,
  };

  res.status(statusCode).json(envelope);
};

export const sendError = (res, message, statusCode = 500, code = 'INTERNAL_SERVER_ERROR', details = undefined, req = {}) => {
  const requestId = req.id || (req.headers && req.headers['x-request-id']) || 'no-request-id';

  const errorObject = {
    code,
    message,
  };

  if (details !== undefined) {
    errorObject.details = details;
  }

  const envelope = {
    success: false,
    error: errorObject,
    timestamp: new Date().toISOString(),
    requestId,
  };

  res.status(statusCode).json(envelope);
};

export const sendNotFound = (res, message = 'The requested resource was not found', req = {}) => {
  sendError(res, message, 404, 'NOT_FOUND', undefined, req);
};

export const sendUnauthorized = (res, message = 'Authentication is required to access this resource', req = {}) => {
  sendError(res, message, 401, 'UNAUTHORIZED', undefined, req);
};

export const sendValidationError = (res, details = [], req = {}) => {
  sendError(res, 'Validation failed for the provided input', 422, 'VALIDATION_ERROR', details, req);
};

